import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }

// --- Types & Constants ---

const LOGO_PARTS = [
  // Row 1
  {
    id: "top-left",
    color: "#F24E1E", // Red-Orange
    borderRadius: "50% 0 0 50%", // Left Semicircle
    row: 0,
    col: 0,
  },
  {
    id: "top-right",
    color: "#FF7262", // Coral
    borderRadius: "0 50% 50% 0", // Right Semicircle
    row: 0,
    col: 1,
  },
  // Row 2
  {
    id: "mid-left",
    color: "#A259FF", // Purple
    borderRadius: "50% 0 0 50%", // Left Semicircle
    row: 1,
    col: 0,
  },
  {
    id: "mid-right",
    color: "#1ABCFE", // Blue
    borderRadius: "50%", // Circle
    row: 1,
    col: 1,
  },
  // Row 3
  {
    id: "bot-left",
    color: "#0ACF83", // Green
    borderRadius: "50% 0 50% 50%", // Teardrop (Round except Top-Right)
    row: 2,
    col: 0,
  },
];

// --- Schema ---



export type FigmaLogoAnimationProps = Record<string, any>;

// --- Components ---

const ShapePiece: React.FC<{
  color: string;
  borderRadius: string;
  size: number;
  delay: number;
  stiffness: number;
  damping: number;
}> = ({ color, borderRadius, size, delay, stiffness, damping }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Create spring animation for scale and entry
  const entrance = spring({
    frame: frame - delay,
    fps,
    config: {
      stiffness,
      damping,
      mass: 0.8,
    },
  });

  // Interpolate properties for a dynamic entrance
  const scale = interpolate(entrance, [0, 1], [0, 1]);
  const rotate = interpolate(entrance, [0, 1], [-45, 0]);
  const opacity = interpolate(entrance, [0, 0.5], [0, 1]);

  return (
    <div
      style={{
        width: size,
        height: size,
        backgroundColor: color,
        borderRadius,
        transform: `scale(${scale}) rotate(${rotate}deg)`,
        opacity,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        willChange: "transform, opacity",
      }}
    />
  );
};

const FigmaLogoAnimation: React.FC<FigmaLogoAnimationProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 6,
  logoSize = 180,
  gap = 0,
  stiffness = 120,
  damping = 14,
  showText = true,
  textColor = "#ffffff",
}) => {
  // Load standard Figma-like font
  useFontLoader(["Inter"]);

  const { width, height, fps } = useVideoConfig();
  const frame = useCurrentFrame();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  
  // Calculate grid metrics
  const gridSize = logoSize; // Total width is roughly logoSize * 2
  const cellSize = gridSize / 2;
  
  // Center calculations
  // The grid is 2 columns wide (cellSize * 2) and 3 rows tall (cellSize * 3)
  const totalWidth = cellSize * 2 + gap;
  const totalHeight = cellSize * 3 + gap * 2;

  // Text Animation
  const textDelay = 25; // Start text after logo pieces start appearing
  const textOpacity = interpolate(
    frame - textDelay * 2,
    [0, 20],
    [0, 1],
    { extrapolateRight: "clamp" }
  );
  const textTranslateY = interpolate(
    frame - textDelay * 2,
    [0, 30],
    [20, 0],
    { extrapolateRight: "clamp", easing: (t) => t * (2 - t) } // EaseOutQuad-ish
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        flexDirection: "column",
        fontFamily: "Inter, sans-serif",
      }}
    >
      <div
        style={{
          display: "grid",
          gridTemplateColumns: `repeat(2, ${cellSize}px)`,
          gridTemplateRows: `repeat(3, ${cellSize}px)`,
          gap: `${gap}px`,
          width: totalWidth,
          height: totalHeight,
          // Position relative for centering
          position: "relative",
          transform: `translateY(${showText ? -30 : 0}px)`, // Slight offset if text is shown
        }}
      >
        {LOGO_PARTS.map((part, index) => {
          // Calculate delay based on index for a stagger effect
          // Order: Top-Left, Top-Right, Mid-Left, Mid-Right, Bot-Left
          const staggerDelay = index * 4; 

          return (
            <div
              key={part.id}
              style={{
                gridRow: part.row + 1,
                gridColumn: part.col + 1,
                width: cellSize,
                height: cellSize,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              <ShapePiece
                color={part.color}
                borderRadius={part.borderRadius}
                size={cellSize}
                delay={staggerDelay}
                stiffness={stiffness}
                damping={damping}
              />
            </div>
          );
        })}
      </div>

      {showText && (
        <div
          style={{
            marginTop: 60,
            color: textColor,
            fontSize: logoSize * 0.4,
            fontWeight: 700,
            letterSpacing: "-0.04em",
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
          }}
        >
          figma
        </div>
      )}
    </AbsoluteFill>
  );
};

export default FigmaLogoAnimation;